let bol;  // declare le tableau bol composé d'objets de classe Bolide

void setup() {
  size(400, 400);
  bol=new Bolide [8]; // initialise la longueur du tableau bol
  for (int i=0; i<bol.length; i++) { // crée le tableau bol
    bol[i]=new Bolide();
  }
}

void draw () {  
  background(255);
  for (int i=0; i<bol.length; i++) { // appelle les fonctions de tous les objets du tableau bol à la fois
    //bol[i].deplace(); // ne pas utiliser si suisSouris est utilisé
    bol[i].suisSouris(); // ne pas utiliser si deplace est utilisé
    bol[i].affiche();
    //bol[i].limite();  // ne pas utiliser si rebondit est utilisé
    bol[i].rebondit(); // ne pas utiliser si limite est utilisé
  }
}

class Bolide {  // déclare la classe d'objets let PVector position; // ces objets sont composés d'objets PVector
  PVector velocite;
  PVector acceleration;

  Bolide() { // initialise les PVector pour chaque objet de classe Bolide
    position=new PVector(random(width), random(height));
    velocite=new PVector(0, 0);
    acceleration=new PVector(0, 0);  // si l'accélération est constante, on a besoin d'une très petite valeur par ex: velocite(0,2) acceleration(0.01,0)
    // on peut utiliser PVector.random() pour une accélération aléatoire, voir ci-dessous
    // l'accélération peut aussi suivre la souris
  }

  // declare les fonctions applicables aux objets de la classe let function deplace() { 
    acceleration=PVector.random2D(); // préciser 2D pour ne pas avoir trois valeurs
    velocite.add(acceleration); // on modifie la vélocité grâce à acceleration
    velocite.limit(5); // limite les déplacements à cinq pixels max
    position.add(velocite); // on modifie la position grâce à velocite
  }

  function suisSouris() { // l'accélération dépend des mouvements de la souris
    PVector souris=new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    souris.sub(position); // le vecteur pointe vers la souris, mais il a une trop grande magnitude
    souris.setMag(0.2);  // on normalise le vecteur souris puis on le divise par cinq
    acceleration=souris;  // l'accélération dépend de la position de la souris
    velocite.add(acceleration); // on modifie la vélocité grâce à acceleration
    velocite.limit(5); // limite les déplacements à cinq pixels max
    position.add(velocite); // on modifie la position grâce à velocite
  }

  function limite() { // si le bolide sort de la fenêtre, il entre à nouveau par le côté opposé
    if (position.x>width) position.x=0;
    if (position.x<0) position.x=width;
    if (position.y>height) position.y=0;
    if (position.y<0) position.y=height;
  }

  function rebondit() { // on teste si les coordonnées de chaque objet sortent de la fenêtre
    if (position.x>width || position.x<0) {
      velocite.x=velocite.x*-1;  // on inverse le sens de déplacement
    }
    if (position.y>height || position.y<0) {
      velocite.y=velocite.y*-1;
    }
  }

  function affiche() {  // les objets de la classe let sont des cercles gris de 8 px
    noStroke();    
    fill(25);
    ellipse(position.x, position.y, 8, 8);
  }
}

